     1→/**
     2→ * VideoPlayerView — isolated expo-video player component.
     3→ *
     4→ * WHY A SEPARATE COMPONENT:
     5→ * expo-video's useVideoPlayer takes a source at initialisation time and the
     6→ * setup callback fires synchronously, so play() is guaranteed to be called
     7→ * before the player reaches readyToPlay. Calling replace() + play() in
     8→ * separate useEffect hooks after the parent sets displayUri is racy:
     9→ *   - statusChange may fire before the listener useEffect runs
    10→ *   - play() may fire before replace() finishes swapping the source
    11→ *
    12→ * Isolating the player here and using key={displayUri} on the parent mount
    13→ * point means every new URI gets a fresh player — no ordering issues, no
    14→ * stale source, no missed events.
    15→ *
    16→ * URI CONTRACT: fileUri MUST be a file:// URI. SAF content:// URIs are
    17→ * always copied to a file:// cache by prepareStatusForViewing() before
    18→ * this component is ever mounted.
    19→ */
    20→import React, { useEffect } from 'react';
    21→import { StyleSheet } from 'react-native';
    22→import { VideoView, useVideoPlayer } from 'expo-video';
    23→
    24→interface VideoPlayerViewProps {
    25→  fileUri: string;
    26→  isActive: boolean;
    27→  onReady: () => void;
    28→  onError: (message: string) => void;
    29→}
    30→
    31→export function VideoPlayerView({
    32→  fileUri,
    33→  isActive,
    34→  onReady,
    35→  onError,
    36→}: VideoPlayerViewProps) {
    37→  // Pass source directly to useVideoPlayer — this is the ONLY correct way to
    38→  // guarantee the source + play() are set before any status events fire.
    39→  // The setup callback is called synchronously during player creation.
    40→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    41→    p.loop = true;
    42→    p.muted = false;
    43→    p.play();
    44→  });
    45→
    46→  // Status listener: subscribe AND check current status immediately so we
    47→  // never miss a readyToPlay event that fired before this useEffect ran.
    48→  useEffect(() => {
    49→    const sub = player.addListener('statusChange', (event) => {
    50→      if (event.status === 'readyToPlay') {
    51→        onReady();
    52→      } else if (event.status === 'error') {
    53→        onError((event as any).error?.message ?? 'Playback error');
    54→      }
    55→    });
    56→
    57→    // Catch the case where readyToPlay fired before the listener was added
    58→    // (can happen when the file is already in ExoPlayer's buffer cache).
    59→    if ((player as any).status === 'readyToPlay') {
    60→      onReady();
    61→    }
    62→
    63→    return () => {
    64→      sub.remove();
    65→      try { player.release(); } catch {}
    66→    };
    67→  }, []); // eslint-disable-line react-hooks/exhaustive-deps
    68→
    69→  // Play / pause based on whether this item is the active slide.
    70→  useEffect(() => {
    71→    try {
    72→      if (isActive) {
    73→        player.play();
    74→      } else {
    75→        player.pause();
    76→      }
    77→    } catch {}
    78→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
    79→
    80→  return (
    81→    <VideoView
    82→      player={player}
    83→      style={StyleSheet.absoluteFill}
    84→      nativeControls={false}
    85→      contentFit="contain"
    86→    />
    87→  );
    88→}
