     1→/**
     2→ * MediaContextSAF — Android 11+ (API 30+) provider.
     3→ *
     4→ * Uses the Storage Access Framework (SAF) to read WhatsApp statuses.
     5→ * The user grants a folder URI once; the grant persists across reboots.
     6→ * A native Java module (SafReaderModule) handles the BFS + file listing
     7→ * on a background thread so the JS thread is never blocked by SAF I/O.
     8→ */
     9→import React, {
    10→  useState,
    11→  useEffect,
    12→  useCallback,
    13→  useRef,
    14→  useMemo,
    15→  ReactNode,
    16→} from 'react';
    17→import { Platform, Alert, Linking, InteractionManager, AppState } from 'react-native';
    18→import * as FileSystem from 'expo-file-system/legacy';
    19→import * as MediaLibrary from 'expo-media-library';
    20→import * as Sharing from 'expo-sharing';
    21→import * as Haptics from 'expo-haptics';
    22→import AsyncStorage from '@react-native-async-storage/async-storage';
    23→import { ThumbnailCache } from '@/lib/thumbnail-cache';
    24→import { cleanupDocumentCache } from '@/lib/video-fallback';
    25→import * as SafReaderModule from '@/modules/saf-reader';
