    42→import { SavedStore } from '@/lib/saved-store';
    43→
    44→// ── In-flight copy deduplication ─────────────────────────────────────────
    45→// Tracks copies currently in progress by item ID so two callers requesting
    46→// the same item (e.g. tap-prefetch in grid + viewer URI-prep) share one
    47→// promise instead of queuing two sequential copies of the same file.
    48→const copyInFlight = new Map<string, Promise<string>>();
    49→
    50→// ── Telemetry ─────────────────────────────────────────────────────────────
    51→const TELEMETRY_KEY = '@statusvault_telemetry';
    52→const TELEMETRY_MAX = 50;
    53→type TelemetrySnapshot = {
    54→  safMountTimesMs: number[];
    55→  directPlaySuccess: number;
    56→  fallbackCopyTriggered: number;
    57→  updatedAt: number;
    58→};
    59→const tel: TelemetrySnapshot = {
    60→  safMountTimesMs: [],
    61→  directPlaySuccess: 0,
    62→  fallbackCopyTriggered: 0,
    63→  updatedAt: 0,
    64→};
    65→let telHydrated = false;
    66→let telFlushTimer: ReturnType<typeof setTimeout> | null = null;
    67→function scheduleTelFlush() {
    68→  if (telFlushTimer) return;
    69→  telFlushTimer = setTimeout(() => {
    70→    telFlushTimer = null;
