   103→export function withTimeout<T>(
   104→  p: Promise<T>,
   105→  ms: number,
   106→  fallback: T,
   107→  label?: string,
   108→): Promise<T> {
   109→  return new Promise<T>(resolve => {
   110→    let settled = false;
   111→    const t = setTimeout(() => {
   112→      if (settled) return;
   113→      settled = true;
   114→      if (label) __DEV__ && console.log(`[Timeout] ${label} timed out after ${ms}ms`);
   115→      resolve(fallback);
   116→    }, ms);
   117→    p.then(
   118→      v => { if (!settled) { settled = true; clearTimeout(t); resolve(v); } },
   119→      _e => { if (!settled) { settled = true; clearTimeout(t); resolve(fallback); } },
   120→    );
   121→  });
   122→}
   123→
   124→export async function pollUntil<T>(
   125→  fn: () => Promise<T>,
   126→  isOk: (v: T) => boolean,
   127→  opts: { maxMs: number; initialDelay: number; backoff?: number; maxDelay?: number },
   128→): Promise<T> {
   129→  const backoff = opts.backoff ?? 1.6;
   130→  const maxDelay = opts.maxDelay ?? 1500;
   131→  const deadline = Date.now() + opts.maxMs;
   132→  let last: T = await fn();
   133→  let delay = opts.initialDelay;
   134→  while (!isOk(last) && Date.now() < deadline) {
   135→    await new Promise(r => setTimeout(r, delay));
   136→    delay = Math.min(Math.round(delay * backoff), maxDelay);
   137→    last = await fn();
   138→  }
   139→  return last;
   140→}
   141→
   142→// ── CRITICAL FIX: Limited Copy Queue (Max 2 Parallel, with Playback Timeout) ──
   143→// Replaces the old serial queue that caused 10+ second freezes
   144→let activeCopies = 0;
   145→const MAX_PARALLEL_COPIES = 2;
   146→const copyWaitingList: (() => Promise<unknown>)[] = [];
   147→
   148→async function runCopy<T>(
   149→  fn: () => Promise<T>,
   150→  timeoutMs: number = 30000,
   151→): Promise<T> {
   152→  activeCopies++;
   153→  try {
   154→    return await withTimeout(fn(), timeoutMs, undefined as any, 'Copy operation');
   155→  } finally {
   156→    activeCopies--;
   157→    if (copyWaitingList.length > 0) {
   158→      const next = copyWaitingList.shift();
   159→      if (next) runCopy(next, timeoutMs);
   160→    }
   161→  }
   162→}
   163→
   164→export function enqueueCopy<T>(
   165→  fn: () => Promise<T>,
   166→  opts?: { timeoutMs?: number; isPlayback?: boolean },
   167→): Promise<T> {
   168→  // Playback copies timeout faster (8s) to fallback to direct SAF play
   169→  const timeoutMs = opts?.isPlayback ? 8000 : (opts?.timeoutMs ?? 30000);
   170→
   171→  // If under limit, run immediately (parallel up to 2)
   172→  if (activeCopies < MAX_PARALLEL_COPIES) {
   173→    return runCopy(fn, timeoutMs);
   174→  }
   175→
   176→  // Otherwise queue it
   177→  return new Promise<T>((resolve, reject) => {
   178→    copyWaitingList.push(async () => {
   179→      try {
   180→        const result = await runCopy(fn, timeoutMs);
   181→        resolve(result);
   182→      } catch (err) {
   183→        reject(err);
   184→      }
   185→    });
   186→  });
   187→}
